(function () {
  "use strict";
  function findHeaders(el) {
    var headers = { "HX-Request": "true" };
    var cur = el;
    while (cur && cur !== document) {
      if (cur.getAttribute) {
        var raw = cur.getAttribute("hx-headers");
        if (raw) {
          try {
            var parsed = JSON.parse(raw);
            for (var k in parsed) {
              if (!(k in headers)) headers[k] = parsed[k];
            }
          } catch (_e) {}
        }
      }
      cur = cur.parentNode;
    }
    return headers;
  }

  function applySwap(target, html, mode) {
    if (!target) return;
    if (mode === "outerHTML") {
      target.outerHTML = html;
    } else if (mode === "beforeend") {
      target.insertAdjacentHTML("beforeend", html);
    } else {
      target.innerHTML = html;
    }
    document.dispatchEvent(new CustomEvent("htmx:afterSettle", { detail: { target: target } }));
  }

  async function handleHxAction(el, method, url) {
    var headers = findHeaders(el);
    var opts = { method: method.toUpperCase(), headers: headers, credentials: "same-origin" };
    if (opts.method !== "GET") {
      var form = el.tagName === "FORM" ? el : el.closest("form");
      if (el.tagName === "FORM" && form) {
        opts.body = new FormData(form);
      } else if (el.getAttribute("hx-vals")) {
        headers["Content-Type"] = "application/json";
        opts.body = el.getAttribute("hx-vals");
      } else if (el.type === "checkbox" && el.name) {
        headers["Content-Type"] = "application/json";
        var payload = {};
        payload[el.name] = el.checked;
        opts.body = JSON.stringify(payload);
      }
    }
    var resp = await fetch(url, opts);
    var text = await resp.text();
    var targetSel = el.getAttribute("hx-target");
    var target = targetSel ? document.querySelector(targetSel) : el;
    var swap = el.getAttribute("hx-swap") || "innerHTML";
    if (resp.ok) {
      applySwap(target, text, swap);
    }
  }

  function bindElement(el) {
    if (el.__hxBound) return;
    var methods = ["get", "post", "put", "patch", "delete"];
    for (var i = 0; i < methods.length; i++) {
      (function (m) {
        var url = el.getAttribute("hx-" + m);
        if (!url) return;
        el.__hxBound = true;
        var evtName = el.tagName === "FORM" ? "submit" : el.type === "checkbox" ? "change" : "click";
        el.addEventListener(evtName, function (ev) {
          if (el.tagName === "A" && el.getAttribute("target") === "_blank") {
            handleHxAction(el, m, url);
            return;
          }
          ev.preventDefault();
          handleHxAction(el, m, url);
        });
      })(methods[i]);
    }
  }

  function scan(root) {
    var nodes = (root || document).querySelectorAll("[hx-get],[hx-post],[hx-put],[hx-patch],[hx-delete]");
    for (var i = 0; i < nodes.length; i++) bindElement(nodes[i]);
  }

  document.addEventListener("DOMContentLoaded", function () { scan(document); });
  document.addEventListener("htmx:afterSettle", function () { scan(document); });
  window.htmx = { process: scan };
})();
